window.SECTIONS = [{"id":"contractions","title":"Contractions","sub":"The short forms people really use","tag":"Learn","topics":[{"id":"k1","title":"I'm, you're, he's, she's, it's, we're, they're","tip":"Be + subject: the verb gets shorter and joins the word before it.","items":[{"en":"I'm tired.","f":"I am tired."},{"en":"I'm at home.","f":"I am at home."},{"en":"You're right about that.","f":"You are right about that."},{"en":"You're very kind.","f":"You are very kind."},{"en":"He's my brother.","f":"He is my brother."},{"en":"She's a doctor.","f":"She is a doctor."},{"en":"It's cold today.","f":"It is cold today."},{"en":"It's late.","f":"It is late."},{"en":"We're ready.","f":"We are ready."},{"en":"We're on our way.","f":"We are on our way."},{"en":"They're my neighbors.","f":"They are my neighbors."},{"en":"They're at work.","f":"They are at work."}]},{"id":"k2","title":"don't, doesn't, didn't","tip":"Do + not. Use doesn't with he, she and it.","items":[{"en":"I don't know.","f":"I do not know."},{"en":"I don't like coffee.","f":"I do not like coffee."},{"en":"We don't have time.","f":"We do not have time."},{"en":"They don't live here.","f":"They do not live here."},{"en":"He doesn't work on Sundays.","f":"He does not work on Sundays."},{"en":"She doesn't eat meat.","f":"She does not eat meat."},{"en":"It doesn't matter.","f":"It does not matter."},{"en":"I didn't see it.","f":"I did not see it."},{"en":"We didn't go out.","f":"We did not go out."},{"en":"She didn't call me.","f":"She did not call me."},{"en":"Don't worry.","f":"Do not worry."},{"en":"Didn't you hear me?","f":"Did you not hear me?"}]},{"id":"k3","title":"isn't, aren't, wasn't, weren't","tip":"Be + not. For I, say I'm not. Nobody says I amn't.","items":[{"en":"It isn't far.","f":"It is not far."},{"en":"This isn't my car.","f":"This is not my car."},{"en":"The store isn't open yet.","f":"The store is not open yet."},{"en":"They aren't here.","f":"They are not here."},{"en":"The kids aren't hungry.","f":"The kids are not hungry."},{"en":"I'm not ready yet.","f":"I am not ready yet."},{"en":"It wasn't easy.","f":"It was not easy."},{"en":"He wasn't at home.","f":"He was not at home."},{"en":"The food wasn't bad.","f":"The food was not bad."},{"en":"We weren't ready.","f":"We were not ready."},{"en":"They weren't happy.","f":"They were not happy."},{"en":"You weren't there.","f":"You were not there."}]},{"id":"k4","title":"can't, couldn't, won't, wouldn't, shouldn't","tip":"Won't is the short form of will not. It sounds like 'wont'.","items":[{"en":"I can't find my keys.","f":"I cannot find my keys."},{"en":"She can't come today.","f":"She cannot come today."},{"en":"I couldn't sleep last night.","f":"I could not sleep last night."},{"en":"We couldn't find a parking spot.","f":"We could not find a parking spot."},{"en":"I won't be late.","f":"I will not be late."},{"en":"It won't take long.","f":"It will not take long."},{"en":"He wouldn't listen to me.","f":"He would not listen to me."},{"en":"I wouldn't do that.","f":"I would not do that."},{"en":"You shouldn't drive so fast.","f":"You should not drive so fast."},{"en":"We shouldn't wait any longer.","f":"We should not wait any longer."},{"en":"The door won't open.","f":"The door will not open."}]},{"id":"k5","title":"I'll, you'll, we'll","tip":"Will + verb for the future and for quick decisions: I'll get it!","items":[{"en":"I'll call you later.","f":"I will call you later."},{"en":"I'll be there at six.","f":"I will be there at six."},{"en":"I'll have a coffee, please.","f":"I will have a coffee, please."},{"en":"You'll love this place.","f":"You will love this place."},{"en":"You'll see.","f":"You will see."},{"en":"We'll talk tomorrow.","f":"We will talk tomorrow."},{"en":"We'll be back soon.","f":"We will be back soon."},{"en":"She'll help you.","f":"She will help you."},{"en":"He'll be fine.","f":"He will be fine."},{"en":"They'll arrive tonight.","f":"They will arrive tonight."},{"en":"It'll be okay.","f":"It will be okay."}]},{"id":"k6","title":"I've, you've, we've","tip":"Have + past participle: I've been, I've seen, I've had.","items":[{"en":"I've been here before.","f":"I have been here before."},{"en":"I've seen that movie.","f":"I have seen that movie."},{"en":"I've had a long day.","f":"I have had a long day."},{"en":"I've finished my work.","f":"I have finished my work."},{"en":"You've been very helpful.","f":"You have been very helpful."},{"en":"You've changed a lot.","f":"You have changed a lot."},{"en":"We've met before.","f":"We have met before."},{"en":"We've lived here for two years.","f":"We have lived here for two years."},{"en":"They've already left.","f":"They have already left."},{"en":"She's never been to New York.","f":"She has never been to New York."},{"en":"He's lost his phone.","f":"He has lost his phone."}]},{"id":"k7","title":"I'd = I would or I had","tip":"I'd like means I would like. I'd better means I had better.","items":[{"en":"I'd like a glass of water.","f":"I would like a glass of water."},{"en":"I'd like to go home.","f":"I would like to go home."},{"en":"I'd love to come.","f":"I would love to come."},{"en":"I'd rather stay in.","f":"I would rather stay in."},{"en":"We'd like to order now.","f":"We would like to order now."},{"en":"She'd like some help.","f":"She would like some help."},{"en":"I'd better go now.","f":"I had better go now."},{"en":"You'd better hurry.","f":"You had better hurry."},{"en":"We'd better leave early.","f":"We had better leave early."},{"en":"I'd never seen snow before.","f":"I had never seen snow before."},{"en":"If I were you, I'd wait.","f":"If I were you, I would wait."}]},{"id":"k8","title":"let's, that's, there's, what's, here's, who's","tip":"Very common at the start of a sentence. Use them all day.","items":[{"en":"Let's go.","f":"Let us go."},{"en":"Let's eat something.","f":"Let us eat something."},{"en":"That's great.","f":"That is great."},{"en":"That's not what I meant.","f":"That is not what I meant."},{"en":"There's a problem.","f":"There is a problem."},{"en":"There's a pharmacy on the corner.","f":"There is a pharmacy on the corner."},{"en":"What's your name?","f":"What is your name?"},{"en":"What's wrong?","f":"What is wrong?"},{"en":"Here's your change.","f":"Here is your change."},{"en":"Here's my number.","f":"Here is my number."},{"en":"Who's that man?","f":"Who is that man?"},{"en":"Who's coming tonight?","f":"Who is coming tonight?"}]},{"id":"k9","title":"The confusing ones","tip":"Same sound, different meaning. It's = it is, but its = belongs to it.","items":[{"en":"It's raining outside.","f":"It is raining outside."},{"en":"The dog wants its toy."},{"en":"You're late.","f":"You are late."},{"en":"Is this your bag?"},{"en":"They're friends.","f":"They are friends."},{"en":"That's their house."},{"en":"Put it over there."},{"en":"He's tired.","f":"He is tired."},{"en":"He's been busy.","f":"He has been busy."},{"en":"She's from Texas.","f":"She is from Texas."},{"en":"She's got two kids.","f":"She has got two kids."}]},{"id":"k10","title":"gonna, wanna, gotta, kinda","tip":"Spoken English only. Say them, but don't write them in an email.","items":[{"en":"I'm gonna call her.","f":"I am going to call her."},{"en":"We're gonna be late.","f":"We are going to be late."},{"en":"It's gonna rain.","f":"It is going to rain."},{"en":"I wanna go home.","f":"I want to go home."},{"en":"Do you wanna eat?","f":"Do you want to eat?"},{"en":"I've gotta go.","f":"I have got to go."},{"en":"You've gotta try this.","f":"You have got to try this."},{"en":"We've gotta leave now.","f":"We have got to leave now."},{"en":"I'm kinda tired.","f":"I am kind of tired."},{"en":"It's kinda cold.","f":"It is kind of cold."},{"en":"I sorta like it.","f":"I sort of like it."}]}],"group":"main","unit":"phrases"},{"id":"vocab","title":"Basic vocabulary","sub":"Everyday words, always inside a phrase","tag":"Learn","topics":[{"id":"v1","title":"Feelings and emotions","tip":"Say how you feel with I'm or I feel.","items":[{"en":"I'm really happy today.","f":"I am really happy today."},{"en":"I'm so tired after work.","f":"I am so tired after work."},{"en":"I feel a little nervous."},{"en":"I'm worried about my mom.","f":"I am worried about my mom."},{"en":"The kids are excited about the trip."},{"en":"I'm bored. There's nothing to do.","f":"I am bored. There is nothing to do."},{"en":"I get frustrated in traffic."},{"en":"I'm proud of my son.","f":"I am proud of my son."},{"en":"I'm sad that you're leaving.","f":"I am sad that you are leaving."},{"en":"She's angry with me.","f":"She is angry with me."},{"en":"I'm a little stressed this week.","f":"I am a little stressed this week."},{"en":"I feel much better now."},{"en":"Don't be scared. It's okay.","f":"Do not be scared. It is okay."},{"en":"I'm surprised to see you here.","f":"I am surprised to see you here."}]},{"id":"v2","title":"Body parts","tip":"At the doctor: my + body part + hurts.","items":[{"en":"My back hurts."},{"en":"I have a headache."},{"en":"My throat is sore."},{"en":"I have a stomachache."},{"en":"My knee hurts when I walk."},{"en":"I hurt my hand at work."},{"en":"My eyes are tired."},{"en":"I have a pain in my chest."},{"en":"My feet are killing me."},{"en":"I cut my finger."},{"en":"My shoulder is stiff."},{"en":"I have a toothache."},{"en":"My ears hurt on the plane."}]},{"id":"v3","title":"Days of the week","tip":"On + day: on Monday. Every Friday. Next Tuesday.","items":[{"en":"I work on Monday."},{"en":"See you on Wednesday."},{"en":"We play soccer every Saturday."},{"en":"I'm off on Fridays.","f":"I am off on Fridays."},{"en":"What are you doing on Sunday?"},{"en":"The store is closed on Sundays."},{"en":"I have a meeting next Tuesday."},{"en":"I saw her last Thursday."},{"en":"The weekend starts on Friday night."},{"en":"Mondays are always busy."},{"en":"Can we meet on Thursday instead?"},{"en":"I go to the gym three days a week."}]},{"id":"v4","title":"Months of the year","tip":"In + month: in March. On + date: on March fifth.","items":[{"en":"My birthday is in July."},{"en":"We're going on vacation in August.","f":"We are going on vacation in August."},{"en":"It's very hot in June.","f":"It is very hot in June."},{"en":"School starts in September."},{"en":"I moved here in January."},{"en":"It gets cold in December."},{"en":"My son was born in April."},{"en":"We got married in May."},{"en":"The rainy season starts in October."},{"en":"I'll see you in February.","f":"I will see you in February."},{"en":"Is your birthday in March?"},{"en":"November is my favorite month."}]},{"id":"v5","title":"Seasons and holidays","tip":"In the summer, in the winter. On Christmas Day. At Christmas.","items":[{"en":"I love the summer."},{"en":"It snows a lot in the winter."},{"en":"The leaves change color in the fall."},{"en":"Spring is my favorite season."},{"en":"What do you do for Christmas?"},{"en":"We spend Thanksgiving with my family."},{"en":"Happy New Year!"},{"en":"Merry Christmas to you and your family."},{"en":"We go to the beach every summer."},{"en":"Are you doing anything for Easter?"},{"en":"We celebrate with a big dinner."},{"en":"Happy birthday! How old are you today?"}]},{"id":"v6","title":"Telling the time","tip":"At + time: at seven thirty. In the morning, at night.","items":[{"en":"What time is it?"},{"en":"It's seven thirty.","f":"It is seven thirty."},{"en":"It's a quarter past nine.","f":"It is a quarter past nine."},{"en":"It's half past six.","f":"It is half past six."},{"en":"It's a quarter to five.","f":"It is a quarter to five."},{"en":"It's almost noon.","f":"It is almost noon."},{"en":"I get up at six in the morning."},{"en":"I go to bed at eleven at night."},{"en":"The movie starts at eight."},{"en":"I'll be there in ten minutes.","f":"I will be there in ten minutes."},{"en":"We're open from nine to five.","f":"We are open from nine to five."},{"en":"Do you have the time?"},{"en":"It's a little after three.","f":"It is a little after three."}]},{"id":"v7","title":"Dates and years","tip":"Say dates with ordinals: November fifth, not November five.","items":[{"en":"What's the date today?","f":"What is the date today?"},{"en":"Today is November fifth."},{"en":"My birthday is on May third."},{"en":"I was born in 1990."},{"en":"We moved here in 2018."},{"en":"The party is on the twenty-first."},{"en":"I'll be back on the first of June.","f":"I will be back on the first of June."},{"en":"The deadline is next Friday, the twelfth."},{"en":"It happened two years ago."},{"en":"We met in the summer of 2015."},{"en":"The baby is due in March."},{"en":"It's the second time this week.","f":"It is the second time this week."}]},{"id":"v8","title":"Prices and money","tip":"How much is it? How much are they? Use is for one thing.","items":[{"en":"How much is it?"},{"en":"How much are these shoes?"},{"en":"It's twenty dollars.","f":"It is twenty dollars."},{"en":"That's too expensive.","f":"That is too expensive."},{"en":"It's on sale today.","f":"It is on sale today."},{"en":"Do you take credit cards?"},{"en":"Can I pay in cash?"},{"en":"Do you have change for a twenty?"},{"en":"Here's your receipt.","f":"Here is your receipt."},{"en":"I need to save money."},{"en":"That's a good deal.","f":"That is a good deal."},{"en":"Can I get a discount?"},{"en":"I'll pay for dinner tonight.","f":"I will pay for dinner tonight."},{"en":"It costs about fifty dollars."}]},{"id":"v9","title":"Family members","tip":"My mom, my dad, my wife, my husband, my kids.","items":[{"en":"This is my wife."},{"en":"My husband works at the hospital."},{"en":"I have two kids, a boy and a girl."},{"en":"My older brother lives in Florida."},{"en":"My younger sister is still in school."},{"en":"My parents are retired."},{"en":"My grandmother is ninety years old."},{"en":"I have a lot of cousins."},{"en":"My aunt and uncle live near us."},{"en":"My son is five years old."},{"en":"My daughter just started college."},{"en":"My in-laws are visiting this weekend."},{"en":"I'm an only child.","f":"I am an only child."}]},{"id":"v10","title":"Colors and describing things","tip":"The describing word goes before the thing: a big house.","items":[{"en":"I have a blue car."},{"en":"I'm looking for a black jacket.","f":"I am looking for a black jacket."},{"en":"It's a big house with a small yard.","f":"It is a big house with a small yard."},{"en":"This phone is cheap, but it's good.","f":"This phone is cheap, but it is good."},{"en":"That's really expensive.","f":"That is really expensive."},{"en":"The room is clean and quiet."},{"en":"The coffee is too hot."},{"en":"These shoes are very comfortable."},{"en":"It's a little old, but it works.","f":"It is a little old, but it works."},{"en":"I like the red one."},{"en":"The new store is huge."},{"en":"The street is dark at night."},{"en":"It's heavy. Can you help me?","f":"It is heavy. Can you help me?"}]},{"id":"v11","title":"Rooms and things at home","tip":"In the kitchen, in the bedroom, on the table.","items":[{"en":"The keys are on the kitchen table."},{"en":"The kids are in their bedroom."},{"en":"I'm in the living room.","f":"I am in the living room."},{"en":"Can you turn off the light?"},{"en":"The bathroom is down the hall."},{"en":"I left my phone on the couch."},{"en":"The fridge is almost empty."},{"en":"Please close the window. It's cold.","f":"Please close the window. It is cold."},{"en":"The towels are in the closet."},{"en":"I need to wash the dishes."},{"en":"We're painting the garage.","f":"We are painting the garage."},{"en":"Turn on the TV, please."},{"en":"There's a lot of noise upstairs.","f":"There is a lot of noise upstairs."}]},{"id":"v12","title":"Clothes","tip":"Put on your jacket. Take off your shoes. Wear a hat.","items":[{"en":"I need a new pair of jeans."},{"en":"Put on your jacket. It's cold.","f":"Put on your jacket. It is cold."},{"en":"Please take off your shoes."},{"en":"I'm wearing a white shirt.","f":"I am wearing a white shirt."},{"en":"These pants are too tight."},{"en":"Do you have this in a smaller size?"},{"en":"Can I try it on?"},{"en":"I like your shoes."},{"en":"I always wear a hat in the sun."},{"en":"My socks are wet."},{"en":"She looks great in that dress."},{"en":"I need a warm coat for the winter."}]},{"id":"v13","title":"Places in town","tip":"At the bank, at the pharmacy, at the supermarket.","items":[{"en":"Is there a bank near here?"},{"en":"I need to go to the pharmacy."},{"en":"I'm at the supermarket right now.","f":"I am at the supermarket right now."},{"en":"The gas station is on the corner."},{"en":"Let's meet at the coffee shop."},{"en":"The post office closes at five."},{"en":"I'm going to the hospital to see my uncle.","f":"I am going to the hospital to see my uncle."},{"en":"The kids are at school."},{"en":"Is the library open today?"},{"en":"There's a nice park downtown.","f":"There is a nice park downtown."},{"en":"I'll drop you off at the bus stop.","f":"I will drop you off at the bus stop."},{"en":"The mall is always crowded on weekends."},{"en":"Where's the nearest restroom?","f":"Where is the nearest restroom?"}]},{"id":"v14","title":"Jobs and work","tip":"I work as a teacher. I work at a hospital. I work in sales.","items":[{"en":"I work as a teacher."},{"en":"I work at a hospital."},{"en":"She's a nurse.","f":"She is a nurse."},{"en":"He's an engineer.","f":"He is an engineer."},{"en":"I work from home three days a week."},{"en":"I start work at eight."},{"en":"I'm looking for a new job.","f":"I am looking for a new job."},{"en":"My boss is very nice."},{"en":"I have a lot of work this week."},{"en":"I work the night shift."},{"en":"I'm off today.","f":"I am off today."},{"en":"My coworkers are great."},{"en":"I got a new job last month."}]},{"id":"v15","title":"Question words","tip":"Who for people, where for places, when for time, why for reasons.","items":[{"en":"Who's that?","f":"Who is that?"},{"en":"What do you need?"},{"en":"Where do you work?"},{"en":"When does the store open?"},{"en":"Why are you late?"},{"en":"How are you doing?"},{"en":"How much does it cost?"},{"en":"How long does it take?"},{"en":"How often do you go to the gym?"},{"en":"Which one do you want?"},{"en":"Whose phone is this?"},{"en":"How many kids do you have?"},{"en":"How far is the airport?"}]},{"id":"v16","title":"In, on, at","tip":"In May, in the morning. On Monday, on the table. At night, at home.","items":[{"en":"I was born in May."},{"en":"We go out in the evening."},{"en":"See you on Monday."},{"en":"The cup is on the table."},{"en":"I'm at home now.","f":"I am at home now."},{"en":"I work at night."},{"en":"She lives in a small town."},{"en":"Meet me at the entrance."},{"en":"The party is on Saturday night."},{"en":"I'll call you in an hour.","f":"I will call you in an hour."},{"en":"The picture is on the wall."},{"en":"I'm at work until five.","f":"I am at work until five."},{"en":"We arrived in Miami on Friday."}]},{"id":"v17","title":"Everyday verbs: get, take, make, do, have, go","tip":"These six verbs do most of the work in English.","items":[{"en":"I get up at six."},{"en":"I'll get some milk on the way home.","f":"I will get some milk on the way home."},{"en":"Take your time."},{"en":"I take the bus to work."},{"en":"Can you take a picture of us?"},{"en":"I'll make some coffee.","f":"I will make some coffee."},{"en":"Don't make noise. The baby is sleeping.","f":"Do not make noise. The baby is sleeping."},{"en":"I need to do the laundry."},{"en":"Can you do me a favor?"},{"en":"Let's have lunch together."},{"en":"I have a question."},{"en":"We go out on Fridays."},{"en":"I'm going to bed.","f":"I am going to bed."},{"en":"It takes twenty minutes to get there."}]}],"group":"main","unit":"phrases"},{"id":"lifesavers","title":"Lifesavers","sub":"Get time, ask again, find the word","tag":"Survive","topics":[{"id":"l1","title":"Buying time","tip":"A short phrase gives you three seconds to think.","items":[{"en":"Let me think."},{"en":"Good question."},{"en":"Hmm, let me see."},{"en":"Give me a second."},{"en":"That's a good question.","f":"That is a good question."},{"en":"How can I put this?"},{"en":"Well, it's hard to say.","f":"Well, it is hard to say."},{"en":"Let me think about that for a moment."},{"en":"I've never thought about that.","f":"I have never thought about that."},{"en":"Wait, let me remember."},{"en":"Oh, that's a tough one.","f":"Oh, that is a tough one."},{"en":"I'm trying to think of the word.","f":"I am trying to think of the word."}]},{"id":"l2","title":"Asking someone to repeat","tip":"Ask without saying sorry three times. One sorry is enough.","items":[{"en":"Sorry, can you repeat that?"},{"en":"Could you say that again, please?"},{"en":"Sorry, I didn't catch that.","f":"Sorry, I did not catch that."},{"en":"Can you speak a little slower, please?"},{"en":"Sorry, what did you say?"},{"en":"Pardon?"},{"en":"Could you say the last part again?"},{"en":"Sorry, it's a little noisy here.","f":"Sorry, it is a little noisy here."},{"en":"Did you say Tuesday or Thursday?"},{"en":"Can you spell that for me?"},{"en":"One more time, please."}]},{"id":"l3","title":"Asking for a word","tip":"When a word is missing, describe it or ask for it.","items":[{"en":"How do you say this in English?"},{"en":"What's the word for this?","f":"What is the word for this?"},{"en":"What do you call the thing you use to open cans?"},{"en":"What does that word mean?"},{"en":"How do you spell it?"},{"en":"How do you pronounce this word?"},{"en":"Is that the right word?"},{"en":"I don't know the word, but it's like a small knife.","f":"I do not know the word, but it is like a small knife."},{"en":"It's the place where you buy medicine.","f":"It is the place where you buy medicine."},{"en":"What's another word for that?","f":"What is another word for that?"},{"en":"Can you write it down for me?"}]},{"id":"l4","title":"Correcting yourself","tip":"Fix it and keep going. People care about the message.","items":[{"en":"What I mean is, I'm busy today.","f":"What I mean is, I am busy today."},{"en":"Sorry, I meant Friday, not Thursday."},{"en":"Let me say that again."},{"en":"No, wait. That's not right.","f":"No, wait. That is not right."},{"en":"I mean, it was okay, not great."},{"en":"Let me put it another way."},{"en":"Actually, it was last week."},{"en":"Sorry, I said that wrong."},{"en":"In other words, I need more time."},{"en":"What I'm trying to say is thank you.","f":"What I am trying to say is thank you."}]},{"id":"l5","title":"When you don't understand","tip":"Say what you understood, then ask about the rest.","items":[{"en":"I'm not sure I understand.","f":"I am not sure I understand."},{"en":"Sorry, I'm a little lost.","f":"Sorry, I am a little lost."},{"en":"What do you mean?"},{"en":"Can you explain that again?"},{"en":"Do you mean today or tomorrow?"},{"en":"Can you give me an example?"},{"en":"So, you want me to wait here?"},{"en":"I understood the first part, but not the second."},{"en":"Let me see if I got that right."},{"en":"Can you say it in a different way?"},{"en":"I'm sorry, my English isn't perfect yet.","f":"I am sorry, my English is not perfect yet."}]},{"id":"l6","title":"Ending a conversation","tip":"End kindly: a reason, a thank you, and a goodbye.","items":[{"en":"Well, it was nice talking to you."},{"en":"I'm sorry, I have to go.","f":"I am sorry, I have to go."},{"en":"I don't want to keep you.","f":"I do not want to keep you."},{"en":"Let's catch up soon."},{"en":"I'll let you go.","f":"I will let you go."},{"en":"Thanks for the chat."},{"en":"I'll see you around.","f":"I will see you around."},{"en":"Take care."},{"en":"Have a good one."},{"en":"Talk to you later."},{"en":"Say hi to your family for me."},{"en":"I've got to run, but let's talk soon.","f":"I have got to run, but let's talk soon."}]}],"group":"main","unit":"phrases"},{"id":"builders","title":"Sentence builders","sub":"Patterns that work for everything","tag":"Build","topics":[{"id":"b1","title":"I'd like to...","tip":"Polite and soft. Perfect for asking, ordering and wishing.","items":[{"en":"I'd like to make an appointment.","f":"I would like to make an appointment."},{"en":"I'd like to try this on.","f":"I would like to try this on."},{"en":"I'd like to order, please.","f":"I would like to order, please."},{"en":"I'd like to speak to the manager.","f":"I would like to speak to the manager."},{"en":"I'd like to learn to swim.","f":"I would like to learn to swim."},{"en":"I'd like to visit Spain one day.","f":"I would like to visit Spain one day."},{"en":"I'd like to pay with my card.","f":"I would like to pay with my card."},{"en":"I'd like to change my reservation.","f":"I would like to change my reservation."},{"en":"I'd like to help you.","f":"I would like to help you."},{"en":"I'd like a table for two, please.","f":"I would like a table for two, please."},{"en":"I'd like to cancel my order.","f":"I would like to cancel my order."}]},{"id":"b2","title":"I used to...","tip":"Something you did before, but not now.","items":[{"en":"I used to live in Mexico."},{"en":"I used to smoke, but I quit."},{"en":"I used to play soccer every day."},{"en":"I used to work at a bank."},{"en":"We used to go to the beach every summer."},{"en":"She used to be my neighbor."},{"en":"I used to hate vegetables."},{"en":"This place used to be a school."},{"en":"I didn't use to like coffee.","f":"I did not use to like coffee."},{"en":"Did you use to live here?"},{"en":"I used to be very shy."}]},{"id":"b3","title":"I've lived here for...","tip":"Started in the past and still true now. Use for or since.","items":[{"en":"I've lived here for five years.","f":"I have lived here for five years."},{"en":"I've worked here for a long time.","f":"I have worked here for a long time."},{"en":"I've known her since high school.","f":"I have known her since high school."},{"en":"We've been married for ten years.","f":"We have been married for ten years."},{"en":"I've had this car since 2019.","f":"I have had this car since 2019."},{"en":"I've been here since eight this morning.","f":"I have been here since eight this morning."},{"en":"How long have you been in this country?"},{"en":"I've worked as a cook for twelve years.","f":"I have worked as a cook for twelve years."},{"en":"I've been sick for three days.","f":"I have been sick for three days."},{"en":"I've studied English for two years.","f":"I have studied English for two years."}]},{"id":"b4","title":"I'm thinking about...","tip":"A plan you're not sure about yet. Use a verb with -ing.","items":[{"en":"I'm thinking about moving.","f":"I am thinking about moving."},{"en":"I'm thinking about buying a new car.","f":"I am thinking about buying a new car."},{"en":"We're thinking about having another baby.","f":"We are thinking about having another baby."},{"en":"I'm thinking about taking a class.","f":"I am thinking about taking a class."},{"en":"I'm thinking about changing jobs.","f":"I am thinking about changing jobs."},{"en":"I'm thinking about you.","f":"I am thinking about you."},{"en":"We're thinking about going out tonight.","f":"We are thinking about going out tonight."},{"en":"He's thinking about selling his house.","f":"He is thinking about selling his house."},{"en":"I'm thinking about getting a dog.","f":"I am thinking about getting a dog."},{"en":"Are you thinking about coming?"}]},{"id":"b5","title":"I'm trying to...","tip":"Something you're working on, or something that's hard.","items":[{"en":"I'm trying to lose weight.","f":"I am trying to lose weight."},{"en":"I'm trying to save money.","f":"I am trying to save money."},{"en":"I'm trying to learn English.","f":"I am trying to learn English."},{"en":"I'm trying to find a parking spot.","f":"I am trying to find a parking spot."},{"en":"I'm trying to call my sister.","f":"I am trying to call my sister."},{"en":"I'm trying to sleep more.","f":"I am trying to sleep more."},{"en":"I'm trying to fix my bike.","f":"I am trying to fix my bike."},{"en":"We're trying to find a bigger apartment.","f":"We are trying to find a bigger apartment."},{"en":"I'm trying to understand.","f":"I am trying to understand."},{"en":"I'm trying to eat healthy.","f":"I am trying to eat healthy."},{"en":"Stop. I'm trying to work.","f":"Stop. I am trying to work."}]},{"id":"b6","title":"It depends on...","tip":"No easy answer? Say what the answer depends on.","items":[{"en":"It depends on the weather."},{"en":"It depends on the price."},{"en":"It depends on my schedule."},{"en":"It depends."},{"en":"It depends on how I feel."},{"en":"It depends on what you need."},{"en":"It depends on the traffic."},{"en":"Everything depends on the doctor."},{"en":"It really depends on the person."},{"en":"It depends on how much time we have."}]},{"id":"b7","title":"The thing is...","tip":"Use it to explain the real problem, gently.","items":[{"en":"The thing is, I'm really busy.","f":"The thing is, I am really busy."},{"en":"The thing is, I don't have a car.","f":"The thing is, I do not have a car."},{"en":"The thing is, it's too expensive.","f":"The thing is, it is too expensive."},{"en":"The thing is, I already said yes."},{"en":"The thing is, we don't have enough time.","f":"The thing is, we do not have enough time."},{"en":"The thing is, I've never done this before.","f":"The thing is, I have never done this before."},{"en":"The problem is, the store is closed."},{"en":"The good thing is, nobody got hurt."},{"en":"The funny thing is, I knew it."},{"en":"The best thing is, it's free.","f":"The best thing is, it is free."}]},{"id":"b8","title":"I'm not sure if...","tip":"If or whether, then the rest of the sentence.","items":[{"en":"I'm not sure if I can come.","f":"I am not sure if I can come."},{"en":"I'm not sure if it's open.","f":"I am not sure if it is open."},{"en":"I'm not sure if she knows.","f":"I am not sure if she knows."},{"en":"I'm not sure if this is right.","f":"I am not sure if this is right."},{"en":"I'm not sure what to do.","f":"I am not sure what to do."},{"en":"I'm not sure where it is.","f":"I am not sure where it is."},{"en":"I'm not sure how to say it.","f":"I am not sure how to say it."},{"en":"I'm not sure when he's coming.","f":"I am not sure when he is coming."},{"en":"I'm not sure it's a good idea.","f":"I am not sure it is a good idea."},{"en":"I don't know if I'll have time.","f":"I do not know if I will have time."}]}],"group":"main","unit":"phrases"},{"id":"questions","title":"Common questions","sub":"The questions people ask, and real answers","tag":"Talk","topics":[{"id":"q1","title":"What do you do?","tip":"This question is about your job. Answer with I'm a... or I work...","items":[{"en":"What do you do?"},{"en":"I'm a teacher.","f":"I am a teacher."},{"en":"I work in a hospital. I'm a nurse.","f":"I work in a hospital. I am a nurse."},{"en":"I work in construction."},{"en":"I'm a stay-at-home mom.","f":"I am a stay-at-home mom."},{"en":"I'm retired now.","f":"I am retired now."},{"en":"I'm between jobs right now.","f":"I am between jobs right now."},{"en":"I run my own business."},{"en":"I'm a student. I study nursing.","f":"I am a student. I study nursing."},{"en":"I work for a big company, in sales."},{"en":"I drive for a delivery company."},{"en":"I'm a cook at a restaurant downtown.","f":"I am a cook at a restaurant downtown."}]},{"id":"q2","title":"Where are you from?","tip":"Say your country or your city. Add one detail.","items":[{"en":"Where are you from?"},{"en":"I'm from Puerto Rico.","f":"I am from Puerto Rico."},{"en":"I'm from Mexico, from a small town near Puebla.","f":"I am from Mexico, from a small town near Puebla."},{"en":"I was born in Colombia, but I grew up here."},{"en":"I'm from Venezuela. I've lived here for six years.","f":"I am from Venezuela. I have lived here for six years."},{"en":"Originally, I'm from the Dominican Republic.","f":"Originally, I am from the Dominican Republic."},{"en":"I'm from Cuba. My family is still there.","f":"I am from Cuba. My family is still there."},{"en":"I'm from here.","f":"I am from here."},{"en":"I'm from the south, near the beach.","f":"I am from the south, near the beach."},{"en":"My parents are from Peru, but I was born in Texas."},{"en":"I'm from a big city. It's very busy.","f":"I am from a big city. It is very busy."}]},{"id":"q3","title":"Where do you live?","tip":"In + city. On + street. Near + place.","items":[{"en":"Where do you live?"},{"en":"I live in Orlando."},{"en":"I live near the hospital."},{"en":"I live in a small apartment downtown."},{"en":"We live in a quiet neighborhood."},{"en":"I live with my parents for now."},{"en":"I live about twenty minutes from here."},{"en":"We just moved to a new house."},{"en":"I live on Main Street."},{"en":"I live in the country. It's very peaceful.","f":"I live in the country. It is very peaceful."},{"en":"I share an apartment with two friends."}]},{"id":"q4","title":"What do you do on weekends?","tip":"Use the present simple for habits: I usually..., I always...","items":[{"en":"What do you do on weekends?"},{"en":"I usually relax at home."},{"en":"I play soccer with my friends."},{"en":"I spend time with my family."},{"en":"I clean the house and do the laundry."},{"en":"We go to the beach when it's sunny.","f":"We go to the beach when it is sunny."},{"en":"I go to church on Sunday."},{"en":"I like to cook a big breakfast."},{"en":"I sleep late. I'm always tired on Saturday.","f":"I sleep late. I am always tired on Saturday."},{"en":"I work on weekends, so I'm off on Mondays.","f":"I work on weekends, so I am off on Mondays."},{"en":"We visit my parents every Sunday."}]},{"id":"q5","title":"How was your day?","tip":"Give one detail. It keeps the conversation going.","items":[{"en":"How was your day?"},{"en":"It was good, thanks. How about you?"},{"en":"It was long. I'm exhausted.","f":"It was long. I am exhausted."},{"en":"Pretty busy, but good."},{"en":"Not bad. Nothing special."},{"en":"It was great. I got some good news."},{"en":"Terrible. Everything went wrong."},{"en":"It went well. I finished early."},{"en":"It was okay. Work was crazy."},{"en":"Quiet. I stayed home and rested."},{"en":"It was a little stressful, but I'm fine.","f":"It was a little stressful, but I am fine."}]},{"id":"q6","title":"Do you have kids?","tip":"Answer, then ask back: How about you?","items":[{"en":"Do you have kids?"},{"en":"Yes, I have two. A boy and a girl."},{"en":"Yes, I have a daughter. She's seven.","f":"Yes, I have a daughter. She is seven."},{"en":"No, not yet."},{"en":"No, I don't have kids, but I have a dog.","f":"No, I do not have kids, but I have a dog."},{"en":"Yes, three. They keep me busy."},{"en":"My kids are grown up now."},{"en":"Yes, a baby boy. He's six months old.","f":"Yes, a baby boy. He is six months old."},{"en":"We're expecting our first baby in May.","f":"We are expecting our first baby in May."},{"en":"No, but I have a lot of nieces and nephews."},{"en":"Yes, two teenagers. Wish me luck."}]},{"id":"q7","title":"What do you like to do?","tip":"Use like or love + verb with -ing.","items":[{"en":"What do you like to do?"},{"en":"I like reading."},{"en":"I love cooking for my family."},{"en":"I like watching soccer."},{"en":"I enjoy going for walks."},{"en":"I love music. I play the guitar."},{"en":"I like going to the movies."},{"en":"I like spending time outside."},{"en":"I'm into video games.","f":"I am into video games."},{"en":"I really like traveling."},{"en":"I don't have much free time, but I like to dance.","f":"I do not have much free time, but I like to dance."}]},{"id":"q8","title":"How long have you lived here?","tip":"Use for with a period of time, since with a start.","items":[{"en":"How long have you lived here?"},{"en":"I've lived here for three years.","f":"I have lived here for three years."},{"en":"Since 2020."},{"en":"Just a few months."},{"en":"All my life."},{"en":"About ten years now."},{"en":"I moved here when I was a kid."},{"en":"Not long. I just arrived in June."},{"en":"Almost five years. Time flies."},{"en":"Since I got married."}]}],"group":"main","unit":"phrases"},{"id":"everyday","title":"Everyday life","sub":"Food, work, weather, shopping and more","tag":"Talk","topics":[{"id":"e1","title":"Food and restaurants","tip":"Order with I'll have... or Can I get...?","items":[{"en":"A table for four, please."},{"en":"Can I see the menu?"},{"en":"What do you recommend?"},{"en":"I'll have the chicken, please.","f":"I will have the chicken, please."},{"en":"Can I get a glass of water?"},{"en":"No onions, please."},{"en":"This is delicious."},{"en":"Can we get the check, please?"},{"en":"Can I get this to go?"},{"en":"I'm allergic to peanuts.","f":"I am allergic to peanuts."},{"en":"I'm starving. Let's eat.","f":"I am starving. Let's eat."},{"en":"I'm full. I can't eat another bite.","f":"I am full. I cannot eat another bite."},{"en":"What are you having?"}]},{"id":"e2","title":"Family and home","tip":"Talk about who lives with you and what you do at home.","items":[{"en":"I live with my wife and two kids."},{"en":"My mom lives with us."},{"en":"We have a small house with a yard."},{"en":"It's my turn to cook tonight.","f":"It is my turn to cook tonight."},{"en":"The kids help with the dishes."},{"en":"We eat dinner together every night."},{"en":"My house is always a mess."},{"en":"We're fixing the roof this month.","f":"We are fixing the roof this month."},{"en":"My brother is staying with us for a while."},{"en":"I love Sunday mornings at home."},{"en":"We just got a new couch."}]},{"id":"e3","title":"Work","tip":"Talk about your day, your schedule and your coworkers.","items":[{"en":"I have a meeting at ten."},{"en":"I'm working late tonight.","f":"I am working late tonight."},{"en":"I got a promotion last month."},{"en":"I'm on vacation next week.","f":"I am on vacation next week."},{"en":"My boss gave me a raise."},{"en":"We're short on staff this week.","f":"We are short on staff this week."},{"en":"I'm really busy at work.","f":"I am really busy at work."},{"en":"I asked for a day off."},{"en":"I'll send you the email today.","f":"I will send you the email today."},{"en":"My shift ends at six."},{"en":"I like my job, but it's hard.","f":"I like my job, but it is hard."}]},{"id":"e4","title":"Sports","tip":"Play soccer, play basketball. Go running, go swimming.","items":[{"en":"Do you like soccer?"},{"en":"I play soccer on Sundays."},{"en":"Who's your favorite team?","f":"Who is your favorite team?"},{"en":"Did you watch the game last night?"},{"en":"We won three to one."},{"en":"It was a tie."},{"en":"I go running every morning."},{"en":"I'm not very good, but I have fun.","f":"I am not very good, but I have fun."},{"en":"My son plays on a team."},{"en":"Let's watch the game at my place."},{"en":"He scored a great goal."},{"en":"I go swimming twice a week."}]},{"id":"e5","title":"The weather","tip":"It's + adjective: it's hot, it's cold, it's windy.","items":[{"en":"It's really hot today.","f":"It is really hot today."},{"en":"It's freezing outside.","f":"It is freezing outside."},{"en":"It looks like rain."},{"en":"It's raining again.","f":"It is raining again."},{"en":"What's the weather like?","f":"What is the weather like?"},{"en":"It's a beautiful day.","f":"It is a beautiful day."},{"en":"It's very humid.","f":"It is very humid."},{"en":"There's a storm coming.","f":"There is a storm coming."},{"en":"It's windy. Hold your hat.","f":"It is windy. Hold your hat."},{"en":"I hope it's sunny this weekend.","f":"I hope it is sunny this weekend."},{"en":"It's cooler in the evening.","f":"It is cooler in the evening."},{"en":"The forecast says rain tomorrow."}]},{"id":"e6","title":"Your town","tip":"Describe where you live: big, small, quiet, busy.","items":[{"en":"I live in a small town."},{"en":"It's quiet and very safe.","f":"It is quiet and very safe."},{"en":"Everybody knows everybody."},{"en":"There isn't much to do at night.","f":"There is not much to do at night."},{"en":"There's a nice park near my house.","f":"There is a nice park near my house."},{"en":"The beach is fifteen minutes away."},{"en":"Traffic is terrible in the morning."},{"en":"It's a great place to raise kids.","f":"It is a great place to raise kids."},{"en":"The food here's amazing.","f":"The food here is amazing."},{"en":"There's a big festival every summer.","f":"There is a big festival every summer."},{"en":"I love my neighborhood."}]},{"id":"e7","title":"Shopping","tip":"Ask where things are, try things on, and pay.","items":[{"en":"Excuse me, where can I find the milk?"},{"en":"Do you have this in blue?"},{"en":"I'm just looking, thanks.","f":"I am just looking, thanks."},{"en":"Where are the fitting rooms?"},{"en":"It's a little too big.","f":"It is a little too big."},{"en":"I'll take it.","f":"I will take it."},{"en":"Can I return this?"},{"en":"I'd like to return this, please.","f":"I would like to return this, please."},{"en":"Do you have it in stock?"},{"en":"Is this on sale?"},{"en":"Where do I pay?"},{"en":"I need a bag, please."}]},{"id":"e8","title":"Health and the doctor","tip":"Say how long: I've had a fever since Monday.","items":[{"en":"I don't feel well.","f":"I do not feel well."},{"en":"I need to see a doctor."},{"en":"I'd like to make an appointment, please.","f":"I would like to make an appointment, please."},{"en":"I've had a fever since Monday.","f":"I have had a fever since Monday."},{"en":"I have a bad cough."},{"en":"I feel dizzy."},{"en":"I'm allergic to penicillin.","f":"I am allergic to penicillin."},{"en":"How often should I take this?"},{"en":"Do I need a prescription?"},{"en":"I think I have the flu."},{"en":"I'm feeling better, thanks.","f":"I am feeling better, thanks."},{"en":"I hurt my ankle playing soccer."},{"en":"I can't sleep at night.","f":"I cannot sleep at night."}]},{"id":"e9","title":"Weekend plans","tip":"Going to for plans: I'm going to visit my mom.","items":[{"en":"What are you doing this weekend?"},{"en":"Any plans for the weekend?"},{"en":"I'm going to visit my mom.","f":"I am going to visit my mom."},{"en":"We're having a barbecue on Saturday.","f":"We are having a barbecue on Saturday."},{"en":"I don't have any plans yet.","f":"I do not have any plans yet."},{"en":"I'm going to rest. I need it.","f":"I am going to rest. I need it."},{"en":"Do you want to come with us?"},{"en":"Let's go to the movies."},{"en":"I'm meeting some friends for dinner.","f":"I am meeting some friends for dinner."},{"en":"We might go to the beach."},{"en":"I have to work on Saturday."},{"en":"How was your weekend?"}]}],"group":"main","unit":"phrases"},{"id":"story","title":"Telling a story","sub":"The past, step by step","tag":"Talk","topics":[{"id":"s1","title":"Yesterday I...","tip":"Past simple for finished actions: went, saw, made, had.","items":[{"en":"Yesterday I went to the store."},{"en":"Yesterday I worked all day."},{"en":"Last night I watched a movie."},{"en":"This morning I woke up late."},{"en":"Last weekend we visited my aunt."},{"en":"Yesterday I cooked dinner for my family."},{"en":"Last Friday I went out with friends."},{"en":"Yesterday I called the doctor."},{"en":"Two days ago I lost my wallet."},{"en":"Last year we went to Mexico."},{"en":"Yesterday I didn't do anything.","f":"Yesterday I did not do anything."}]},{"id":"s2","title":"First, then, after that","tip":"Connectors tell the listener the order. Use them slowly.","items":[{"en":"First, I took a shower."},{"en":"Then I had breakfast."},{"en":"After that, I drove to work."},{"en":"Next, I checked my email."},{"en":"Then we went to the park."},{"en":"After lunch, we took a nap."},{"en":"Before dinner, I went for a walk."},{"en":"After that, we watched TV."},{"en":"Later, my brother came over."},{"en":"At the end of the day, I was exhausted."},{"en":"Meanwhile, the kids were playing."}]},{"id":"s3","title":"Suddenly","tip":"Use it for the surprise moment of your story.","items":[{"en":"Suddenly, the lights went out."},{"en":"Suddenly, it started to rain."},{"en":"All of a sudden, my phone rang."},{"en":"Suddenly, I heard a loud noise."},{"en":"Out of nowhere, a dog ran into the street."},{"en":"Suddenly, I remembered my keys."},{"en":"I was walking home when I saw an old friend."},{"en":"We were eating when the power went out."},{"en":"I was driving when my car stopped."},{"en":"Then something strange happened."}]},{"id":"s4","title":"In the end","tip":"Finish your story with the result.","items":[{"en":"In the end, everything was fine."},{"en":"In the end, we missed the bus."},{"en":"Finally, we got home at midnight."},{"en":"Luckily, nobody got hurt."},{"en":"In the end, I bought the cheaper one."},{"en":"At last, the doctor called me."},{"en":"In the end, it was a great day."},{"en":"So, that's what happened.","f":"So, that is what happened."},{"en":"Long story short, I got the job."},{"en":"Anyway, we had a lot of fun."}]},{"id":"s5","title":"Irregular verbs: go, see, have, make","tip":"Learn them in pairs: go, went. See, saw. Have, had. Make, made.","items":[{"en":"I went to the beach."},{"en":"We went home early."},{"en":"I saw my cousin at the store."},{"en":"Did you see that?"},{"en":"I had a great time."},{"en":"We had pizza for dinner."},{"en":"I made a mistake."},{"en":"She made a cake for my birthday."},{"en":"He came to my house."},{"en":"I got a new phone."},{"en":"I took the kids to school."},{"en":"I gave her a present."}]},{"id":"s6","title":"Irregular verbs: say, tell, think, buy","tip":"Say, said. Tell, told. Think, thought. Buy, bought.","items":[{"en":"She said yes."},{"en":"He told me the truth."},{"en":"I thought it was closed."},{"en":"I bought some bread."},{"en":"I found my keys under the bed."},{"en":"We left at seven."},{"en":"I knew it."},{"en":"I ate too much."},{"en":"I drank a lot of water."},{"en":"I forgot my lunch at home."},{"en":"I felt sick in the morning."},{"en":"I slept nine hours."}]},{"id":"s7","title":"A bad day","tip":"Tell a small problem with a beginning, a middle and an end.","items":[{"en":"I had a terrible day."},{"en":"First, my alarm didn't go off.","f":"First, my alarm did not go off."},{"en":"I missed the bus and got to work late."},{"en":"My boss wasn't happy.","f":"My boss was not happy."},{"en":"Then I spilled coffee on my shirt."},{"en":"At lunch, I forgot my wallet."},{"en":"On the way home, it started to pour."},{"en":"I got home soaking wet."},{"en":"But my kids made me dinner."},{"en":"In the end, it wasn't so bad.","f":"In the end, it was not so bad."}]},{"id":"s8","title":"A trip","tip":"Where, who, what you did, how it was.","items":[{"en":"Last summer we went to Florida."},{"en":"We drove for ten hours."},{"en":"We stayed in a small hotel near the beach."},{"en":"The weather was perfect."},{"en":"We swam every day."},{"en":"We tried a lot of new food."},{"en":"The kids loved the water park."},{"en":"One day we got lost."},{"en":"It was the best vacation ever."},{"en":"I can't wait to go back.","f":"I cannot wait to go back."}]}],"group":"main","unit":"phrases"},{"id":"react","title":"Reacting and giving opinions","sub":"Agree, disagree, and show interest","tag":"Talk","topics":[{"id":"r1","title":"Giving your opinion","tip":"Start soft: I think, in my opinion, for me.","items":[{"en":"I think it's a good idea.","f":"I think it is a good idea."},{"en":"In my opinion, it's too expensive.","f":"In my opinion, it is too expensive."},{"en":"For me, family comes first."},{"en":"I feel like it's too late.","f":"I feel like it is too late."},{"en":"If you ask me, it's not worth it.","f":"If you ask me, it is not worth it."},{"en":"I believe you're right.","f":"I believe you are right."},{"en":"Personally, I prefer the beach."},{"en":"To be honest, I didn't like it.","f":"To be honest, I did not like it."},{"en":"I don't think so.","f":"I do not think so."},{"en":"I guess it's okay.","f":"I guess it is okay."}]},{"id":"r2","title":"Agreeing","tip":"Short and natural. You can agree with two words.","items":[{"en":"I agree."},{"en":"I totally agree."},{"en":"You're right.","f":"You are right."},{"en":"Exactly."},{"en":"That's true.","f":"That is true."},{"en":"Me too."},{"en":"Me neither."},{"en":"Good point."},{"en":"Same here."},{"en":"I think so too."},{"en":"Absolutely."}]},{"id":"r3","title":"Disagreeing politely","tip":"Soften it first: I see your point, but...","items":[{"en":"I don't agree.","f":"I do not agree."},{"en":"I see your point, but I'm not sure.","f":"I see your point, but I am not sure."},{"en":"I'm not so sure about that.","f":"I am not so sure about that."},{"en":"I see it a little differently."},{"en":"Maybe, but I think it's too risky.","f":"Maybe, but I think it is too risky."},{"en":"That's true, but it's expensive.","f":"That is true, but it is expensive."},{"en":"I don't really agree with that.","f":"I do not really agree with that."},{"en":"Sorry, but I think you're wrong.","f":"Sorry, but I think you are wrong."},{"en":"I understand, but I don't like it.","f":"I understand, but I do not like it."},{"en":"Let's agree to disagree."}]},{"id":"r4","title":"Surprise and interest","tip":"Your voice goes up. It shows you're listening.","items":[{"en":"Really?"},{"en":"No way!"},{"en":"Are you serious?"},{"en":"Wow, that's amazing!","f":"Wow, that is amazing!"},{"en":"I can't believe it!","f":"I cannot believe it!"},{"en":"That's interesting.","f":"That is interesting."},{"en":"Oh, I didn't know that.","f":"Oh, I did not know that."},{"en":"That's crazy!","f":"That is crazy!"},{"en":"You're kidding!","f":"You are kidding!"},{"en":"Seriously?"},{"en":"That's so cool.","f":"That is so cool."}]},{"id":"r5","title":"Understanding and making sense","tip":"Show the other person that you follow the idea.","items":[{"en":"That makes sense."},{"en":"I see."},{"en":"Oh, I get it now."},{"en":"Got it."},{"en":"Okay, I understand."},{"en":"That explains it."},{"en":"Now I see what you mean."},{"en":"Fair enough."},{"en":"I hear you."},{"en":"That's a good way to put it.","f":"That is a good way to put it."}]},{"id":"r6","title":"When you're not sure","tip":"It's okay not to have an opinion yet.","items":[{"en":"I'm not sure.","f":"I am not sure."},{"en":"Maybe."},{"en":"I don't know yet.","f":"I do not know yet."},{"en":"I'll think about it.","f":"I will think about it."},{"en":"It's hard to say.","f":"It is hard to say."},{"en":"I'm not sure about that.","f":"I am not sure about that."},{"en":"Could be."},{"en":"I have no idea."},{"en":"I haven't decided yet.","f":"I have not decided yet."},{"en":"Let me think about it."}]},{"id":"r7","title":"Follow-up questions","tip":"One more question shows real interest.","items":[{"en":"What happened next?"},{"en":"And then what?"},{"en":"How did you feel?"},{"en":"Why do you think that happened?"},{"en":"What did you do?"},{"en":"How was it?"},{"en":"Did you like it?"},{"en":"Who did you go with?"},{"en":"Are you going to go back?"},{"en":"Tell me more."},{"en":"What do you mean by that?"}]},{"id":"r8","title":"Good news and bad news","tip":"Match the feeling: happy for them, or sorry.","items":[{"en":"Congratulations!"},{"en":"That's great news!","f":"That is great news!"},{"en":"I'm so happy for you.","f":"I am so happy for you."},{"en":"Good for you!"},{"en":"You deserve it."},{"en":"I'm sorry to hear that.","f":"I am sorry to hear that."},{"en":"Oh no, that's terrible.","f":"Oh no, that is terrible."},{"en":"That's too bad.","f":"That is too bad."},{"en":"I hope everything is okay."},{"en":"Let me know if you need anything."},{"en":"That must be hard."}]}],"group":"main","unit":"phrases"},{"id":"mistakes","title":"Common mistakes","sub":"Say it the right way","tag":"Fix","topics":[{"id":"x1","title":"He, she, it + s","tip":"With he, she and it, the verb ends in -s: she works, it fails.","items":[{"en":"She works at a bank."},{"en":"He lives in Texas."},{"en":"It learns from examples."},{"en":"My son plays soccer."},{"en":"The store opens at nine."},{"en":"It fails every time."},{"en":"She speaks three languages."},{"en":"He doesn't like fish.","f":"He does not like fish."},{"en":"My phone needs a new battery."},{"en":"Does she know?"},{"en":"My mom calls me every day."}]},{"id":"x2","title":"Present simple for general facts","tip":"Facts and habits use the present simple, not the past.","items":[{"en":"We show it a lot of data."},{"en":"The bus comes every hour."},{"en":"Water boils at one hundred degrees."},{"en":"I always drink coffee in the morning."},{"en":"The kids go to bed at eight."},{"en":"This app helps you learn words."},{"en":"He usually works from home."},{"en":"The sun rises in the east."},{"en":"People love this restaurant."},{"en":"It rains a lot in May."}]},{"id":"x3","title":"Good and well","tip":"Good describes a thing. Well describes how you do something.","items":[{"en":"My day was very good."},{"en":"My day went well."},{"en":"You speak English well."},{"en":"She's a good cook.","f":"She is a good cook."},{"en":"She cooks well."},{"en":"I'm doing well, thanks.","f":"I am doing well, thanks."},{"en":"The food is good here."},{"en":"The interview went well."},{"en":"He plays the guitar really well."},{"en":"It looks good on you."}]},{"id":"x4","title":"Play soccer","tip":"In the US, football is a different game. Say play soccer.","items":[{"en":"I play soccer on weekends."},{"en":"Do you play soccer?"},{"en":"My kids play soccer at school."},{"en":"We practice on Tuesdays."},{"en":"I like to watch soccer on TV."},{"en":"He plays basketball after work."},{"en":"Let's play a game."},{"en":"Soccer is the most popular sport in the world."},{"en":"I used to play soccer when I was young."},{"en":"American football is very different."}]},{"id":"x5","title":"Actually and currently","tip":"Actually means in fact. Currently means right now.","items":[{"en":"Actually, I'm from Colombia.","f":"Actually, I am from Colombia."},{"en":"I'm actually pretty tired.","f":"I am actually pretty tired."},{"en":"Actually, I changed my mind."},{"en":"I currently work at a hospital."},{"en":"I'm currently looking for a job.","f":"I am currently looking for a job."},{"en":"Right now, I live with my parents."},{"en":"At the moment, I'm very busy.","f":"At the moment, I am very busy."},{"en":"It's actually easier than it looks.","f":"It is actually easier than it looks."},{"en":"He's currently on vacation.","f":"He is currently on vacation."},{"en":"Actually, that's not true.","f":"Actually, that is not true."}]},{"id":"x6","title":"Age: I'm 30 years old","tip":"In English, you are an age. You don't have it.","items":[{"en":"I'm 30 years old.","f":"I am 30 years old."},{"en":"I'm thirty.","f":"I am thirty."},{"en":"How old are you?"},{"en":"My son is ten years old."},{"en":"She's almost forty.","f":"She is almost forty."},{"en":"He just turned eighteen."},{"en":"I'm in my thirties.","f":"I am in my thirties."},{"en":"My grandmother is ninety-two."},{"en":"How old is your daughter?"},{"en":"We're the same age.","f":"We are the same age."}]},{"id":"x7","title":"I've lived here for one year","tip":"Still true now? Use I've + verb, with for or since.","items":[{"en":"I've lived here for one year.","f":"I have lived here for one year."},{"en":"I've lived here since 2024.","f":"I have lived here since 2024."},{"en":"I've worked here for two months.","f":"I have worked here for two months."},{"en":"I've known him since we were kids.","f":"I have known him since we were kids."},{"en":"She's been sick since Monday.","f":"She has been sick since Monday."},{"en":"We've been together for five years.","f":"We have been together for five years."},{"en":"I've had this phone for a long time.","f":"I have had this phone for a long time."},{"en":"How long have you worked there?"},{"en":"I've been waiting for twenty minutes.","f":"I have been waiting for twenty minutes."},{"en":"I haven't seen her since the summer.","f":"I have not seen her since the summer."}]},{"id":"x8","title":"One no is enough","tip":"English uses one negative: I don't know anybody.","items":[{"en":"I don't know anybody here.","f":"I do not know anybody here."},{"en":"I don't have anything to do.","f":"I do not have anything to do."},{"en":"I didn't see anyone.","f":"I did not see anyone."},{"en":"I know nobody here."},{"en":"There's nothing in the fridge.","f":"There is nothing in the fridge."},{"en":"I don't want anything, thanks.","f":"I do not want anything, thanks."},{"en":"He never says anything."},{"en":"I didn't go anywhere.","f":"I did not go anywhere."},{"en":"Nobody called me."},{"en":"I don't need any help.","f":"I do not need any help."}]},{"id":"x9","title":"Depends on, explain to","tip":"Depends on, not depends of. Explain it to me, not explain me.","items":[{"en":"It depends on you."},{"en":"It depends on the day."},{"en":"Can you explain it to me?"},{"en":"Let me explain it to you."},{"en":"Can you explain how it works?"},{"en":"He explained the problem to us."},{"en":"I'll explain everything to her later.","f":"I will explain everything to her later."},{"en":"Please explain the rules to the kids."},{"en":"It depends on what time you finish."},{"en":"It doesn't depend on me.","f":"It does not depend on me."}]},{"id":"x10","title":"False friends","tip":"Assist = help. Attend = go to. Embarrassed = ashamed. Library = books.","items":[{"en":"I attended the meeting."},{"en":"I go to the library to borrow books."},{"en":"I buy books at the bookstore."},{"en":"Can I help you?"},{"en":"The nurse assisted the doctor."},{"en":"I was so embarrassed."},{"en":"She's pregnant.","f":"She is pregnant."},{"en":"I realized I was wrong."},{"en":"I finally carried out my plan."},{"en":"I'm going to the career fair.","f":"I am going to the career fair."},{"en":"Excuse me, where's the exit?","f":"Excuse me, where is the exit?"}]},{"id":"x11","title":"Small words that change everything","tip":"Say the subject: it's raining, not is raining.","items":[{"en":"It's raining.","f":"It is raining."},{"en":"It's important to rest.","f":"It is important to rest."},{"en":"It's easy.","f":"It is easy."},{"en":"There are many people here."},{"en":"I'm married.","f":"I am married."},{"en":"I'm hungry.","f":"I am hungry."},{"en":"I'm afraid of dogs.","f":"I am afraid of dogs."},{"en":"She's right.","f":"She is right."},{"en":"I'm in a hurry.","f":"I am in a hurry."},{"en":"I'm used to it.","f":"I am used to it."}]}],"group":"main","unit":"phrases"}];
